export default behaviour({
  name: 'Laps',
  state: { laps: 0, best: 0, last: -1 },
  inputs: ['cross'],
  outputs: ['laps', 'best'],
  on: {
    cross() {
      const t = this.now();
      if (this.state.last < 0) { this.state.last = t; return; }
      const lap = t - this.state.last;
      if (lap < 3) return;
      this.state.laps += 1;
      if (!this.state.best || lap < this.state.best) this.state.best = Math.round(lap * 10) / 10;
      this.state.last = t;
    }
  }
});

