export default behaviour({
  name: 'Waves',
  state: { on: false },
  inputs: ['begin'],
  outputs: [],
  on: {
    begin() { if (!this.state.on) { this.state.on = true; this.after(1, 'wave'); } }
  },
  wave() {
    if (kit.spawner.count('enemy') < 5) {
      const t = this.find('Enemy');
      const ids = kit.spawner.spawn({ kind: 'enemy', template: t ? t.uuid : '', count: 1, hp: 1, speed: 0, spread: 6, removeAfter: 0 });
      for (const id of ids || []) this.after(8, 'expire', id);
    }
    this.after(1, 'wave');
  },
  expire(id) { kit.health.damage(id, 999); }
});

export default behaviour({
  name: 'Teams',
  state: { team: {}, nRed: 0, nBlue: 0, red: 0, blue: 0 },
  inputs: ['join', 'hit'],
  outputs: ['red', 'blue'],
  on: {
    join({ by }) { this.place(by); },
    hit({ by }) { const t = this.place(by); this.state[t] += 1; }
  },
  place(by) {
    if (!this.state.team[by]) {
      const t = this.state.nRed <= this.state.nBlue ? 'red' : 'blue';
      this.state.team[by] = t;
      if (t === 'red') this.state.nRed += 1; else this.state.nBlue += 1;
    }
    return this.state.team[by];
  }
});

