export default behaviour({
  name: 'Plates',
  state: { l: 0, r: 0, shut: true },
  inputs: ['inL', 'outL', 'inR', 'outR'],
  outputs: ['shut'],
  on: {
    inL() { this.state.l += 1; this.check(); },
    outL() { this.state.l = Math.max(0, this.state.l - 1); this.check(); },
    inR() { this.state.r += 1; this.check(); },
    outR() { this.state.r = Math.max(0, this.state.r - 1); this.check(); }
  },
  check() { this.state.shut = !(this.state.l > 0 && this.state.r > 0); }
});

